#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure for a binary search tree node
typedef struct Node {
    int value;
    struct Node* left;
    struct Node* right;
} Node;

// Function to create a new node
Node* createNode(int value) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory error
");
        return NULL;
    }
    newNode->value = value;
    newNode->left = newNode->right = NULL;
    return newNode;
}

// Function to insert a node into the binary search tree
void insertNode(Node** root, int value) {
    if (*root == NULL) {
        *root = createNode(value);
    } else if (value < (*root)->value) {
        insertNode(&((*root)->left), value);
    } else if (value > (*root)->value) {
        insertNode(&((*root)->right), value);
    }
}

// Function to perform inorder traversal of the binary search tree
void inorder(Node* root) {
    if (root) {
        inorder(root->left);
        printf("%d ", root->value);
        inorder(root->right);
    }
}

// Function to perform preorder traversal of the binary search tree
void preorder(Node* root) {
    if (root) {
        printf("%d ", root->value);
        preorder(root->left);
        preorder(root->right);
    }
}

// Function to perform postorder traversal of the binary search tree
void postorder(Node* root) {
    if (root) {
        postorder(root->left);
        postorder(root->right);
        printf("%d ", root->value);
    }
}

int main(int argc, char* argv[]) {
    Node* root = NULL;
    if (argc < 2) {
        printf("Usage: %s <mode> [values]
", argv[0]);
        return 1;
    }
    char* mode = argv[1];
    if (strcmp(mode, "in") == 0) {
        for (int i = 2; i < argc; i++) {
            insertNode(&root, atoi(argv[i]));
        }
        inorder(root);
    } else if (strcmp(mode, "pre") == 0) {
        for (int i = 2; i < argc; i++) {
            insertNode(&root, atoi(argv[i]));
        }
        preorder(root);
    } else if (strcmp(mode, "post") == 0) {
        for (int i = 2; i < argc; i++) {
            insertNode(&root, atoi(argv[i]));
        }
        postorder(root);
    } else {
        printf("Invalid mode
");
    }
    printf("\n");
    return 0;
}
